import org.joget.apps.app.model.PluginDefaultProperties;
import org.joget.plugin.base.PluginManager;
  
public FormRowSet load(Element element, String primaryKey, FormData formData) {
    FormRowSet rows = new FormRowSet();
    AppDefinition appDef = AppUtil.getCurrentAppDefinition();
    String pluginId = "org.joget.apps.app.lib.EmailTool";
    PluginDefaultPropertiesDao pluginDefaultPropertiesDao = (PluginDefaultPropertiesDao) AppUtil.getApplicationContext().getBean("pluginDefaultPropertiesDao");
  
    if (appDef != null) {
        //check for existing default properties
        PluginDefaultProperties existingPluginDefaultProperties = pluginDefaultPropertiesDao.loadById(pluginId, appDef);
        if (existingPluginDefaultProperties != null) {
            //existing found
            JSONObject json;
            FormRow r = new FormRow();
            Map propertyMap = new HashMap();
            
            String properties = existingPluginDefaultProperties.getPluginProperties();
            
            
            if (properties != null && properties.trim().length() > 0) {
                json = new JSONObject(properties);
            }
            
            Iterator keys = json.keys();

            while( keys.hasNext() ) {
                String key = (String)keys.next();
                if ( json.get(key) instanceof JSONObject ) {
                    //nested
                }else{
                    r.setProperty(key, json.get(key).toString());
                }
            }
            rows.add(r);
        }else{

        }
    }
     
    return rows;
}
  
//call load method with injected variable
return load(element, primaryKey, formData);

import org.joget.apps.app.model.AppDefinition;
import org.joget.apps.app.service.AppUtil;
import org.joget.apps.form.model.Element;
import org.joget.apps.form.model.FormData;
import org.joget.apps.form.model.FormRow;
import org.joget.apps.form.model.FormRowSet;
import org.json.JSONObject;
import org.joget.plugin.base.Plugin;
import org.joget.plugin.base.PluginManager;
import org.joget.apps.app.dao.PluginDefaultPropertiesDao;
import org.joget.apps.app.model.PluginDefaultProperties;
import org.joget.plugin.base.PluginManager;
   
public FormRowSet store(Element element, FormRowSet rows, FormData formData) {
    
    AppDefinition appDef = AppUtil.getCurrentAppDefinition();
    PluginManager pluginManager = (PluginManager) AppUtil.getApplicationContext().getBean("pluginManager");
    PluginDefaultPropertiesDao pluginDefaultPropertiesDao = (PluginDefaultPropertiesDao) AppUtil.getApplicationContext().getBean("pluginDefaultPropertiesDao");
    
    String pluginId = "org.joget.apps.app.lib.EmailTool";
    PluginDefaultProperties pluginDefaultProperties = null;
    pluginDefaultProperties = new PluginDefaultProperties();
    pluginDefaultProperties.setAppDefinition(appDef);
    pluginDefaultProperties.setId(pluginId);
    
    Plugin plugin = (Plugin) pluginManager.getPlugin(pluginId);
    try {
        pluginDefaultProperties.setPluginName(plugin.getName());
        pluginDefaultProperties.setPluginDescription(plugin.getDescription());
    }catch (Exception e) {
        
    }
    
    if (rows != null && !rows.isEmpty()) {
        
        //Get the submitted data
        FormRow row = rows.get(0);
        
        JSONObject json = new JSONObject();
        
        //Add / Update each Environment Variable
        for (Object key : row.keySet()) {
            String fieldId = (String) key;
            String value = row.getProperty(fieldId);
             
            if (!fieldId.isEmpty()){
                json.accumulate(fieldId, value);
            }
        }
        
        pluginDefaultProperties.setPluginProperties(json.toString());
        
        //check for existing default properties
        PluginDefaultProperties existingPluginDefaultProperties = pluginDefaultPropertiesDao.loadById(pluginId, appDef);
        if (existingPluginDefaultProperties != null) {
            pluginDefaultPropertiesDao.update(pluginDefaultProperties);
        }else{
            pluginDefaultPropertiesDao.add(pluginDefaultProperties);
        }
    }
     
    return rows;
}
  
//call store method with injected variable
return store(element, rows, formData);
